ST = {'Alabama':'AL','Alaska':'AK','Arizona':'AZ','Arkansas':'AR','California':'CA','Colorado':'CO','Connecticut':'CT','Delaware':'DE','District of Columbia':'DC','Florida':'FL','Georgia':'GA','Idaho':'ID','Illinois':'IL','Indiana':'IN','Iowa':'IA','Kansas':'KS','Kentucky':'KY','Louisiana':'LA','Maine':'ME','Maryland':'MD','Massachusetts':'MA','Michigan':'MI','Minnesota':'MN','Mississippi':'MS','Missouri':'MO','Montana':'MT','Nebraska':'NE','Nevada':'NV','New Hampshire':'NH','New Jersey':'NJ','New Mexico':'NM','New York':'NY','North Carolina':'NC','North Dakota':'ND','Ohio':'OH','Oklahoma':'OK','Oregon':'OR','Pennsylvania':'PA','Rhode Island':'RI','South Carolina':'SC','South Dakota':'SD','Tennessee':'TN','Texas':'TX','Utah':'UT','Vermont':'VT','Virginia':'VA','Washington':'WA','West Virginia':'WV','Wisconsin':'WI','Wyoming':'WY'}
CA = {'Alberta':'AB','British Columbia':'BC','Manitoba':'MB','New Brunswick':'NB','Newfoundland and Labrador':'NL','Nova Scotia':'NS','Northwest Territories':'NT','Nunavut':'NU','Ontario':'ON','Prince Edward Island':'PE','Quebec':'QC','Saskatchewan':'SK','Yukon':'YT'}
MX = {'Aguascalientes':'Ags.','Baja California':'B.C.','Baja California Sur':'B.C.S.','Campeche':'Camp.','Chiapas':'Chis.','Chihuahua':'Chih.','Coahuila':'Coah.','Colima':'Col.','Durango':'Dgo.','Guanajuato':'Gto.','Guerrero':'Gro.','Hidalgo':'Hgo.','Jalisco':'Jal.','México':'Méx.','Mexico City':'CDMX','Michoacán':'Mich.','Morelos':'Mor.','Nayarit':'Nay.','Nuevo León':'N.L.','Oaxaca':'Oax.','Puebla':'Pue.','Querétaro':'Qro.','Quintana Roo':'Q.R.','San Luis Potosí':'S.L.P.','Sinaloa':'Sin.','Sonora':'Son.','Tabasco':'Tab.','Tamaulipas':'Tamps.','Tlaxcala':'Tlax.','Veracruz':'Ver.','Yucatán':'Yuc.','Zacatecas':'Zac.'}
def label(name, country, admin1):
    if country == 'US': return f"{name}, {ST.get(admin1, admin1)}"
    if country == 'CA': return f"{name}, {CA.get(admin1, admin1)}"
    if name == 'Mexico City': return 'Mexico City, MX'
    return f"{name}, {MX.get(admin1, admin1)} MX"
